(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.008+t*0.15)*25 + Math.cos((y+w1y)*0.012-t*0.1)*18;
  const w2y = Math.cos((y+w1y)*0.009-t*0.18)*22 + Math.sin((x+w1x)*0.011+t*0.22)*16;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65)*55, 0.11, 2.1, 1.3],
    [400+Math.cos(t*0.55+2)*85, 200+Math.sin(t*0.75+1)*65, 0.065, 2.4, 0.85],
    [200+Math.sin(t*0.38+6)*95, 220+Math.cos(t*0.48+4)*75, 0.13, 1.6, 1.05],
    [300+Math.cos(t*0.42+1)*105, 30+Math.sin(t*0.58+5)*85, 0.075, 2.8, 0.95]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    const inhW = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    const cross = Math.sin(d*f*0.5 - t*sp*0.3 + 0.8) * Math.cos(d*f*0.9 + t*sp*0.4 - 0.6);
    aS += wave * w;
    iS += inhW * w;
    cS += cross * w;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, crs = cS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07*sy*0.05+t*0.6)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = Math.sin(dist*0.03+ang*6-t*0.8)*Math.cos(dist*0.07-ang*2+t*1.1)*0.25;
  const micro = (Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.7)+Math.sin((sx-sy)*0.25+t*4))*0.08;
  const feed = 0.055 + Math.sin(dist*0.008+t*0.2)*0.015;
  const kill = 0.062 + Math.cos(ang*2+t*0.3)*0.01;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + sp1)*2.2);
  const rd2 = Math.tanh((crs*0.5 + sp2 + micro - rd1*feed + rd1*rd1*kill)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend = rd1*0.5 + rd2*0.25 + cell*0.25;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,95],[18,90,125],[30,140,135],[90,175,120],
    [185,190,65],[220,160,55],[210,110,65],[180,65,75],[120,35,65],
    [65,18,55],[30,12,48],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(rd1*Math.PI)*0.15 + Math.abs(rd2)*0.1;
  const edge = Math.abs(rd1)>0.65 ? 1.2 : Math.abs(rd2)>0.6 ? 1.1 : 0.95;
  const shimmer = 1.0 + Math.sin(rd1*8+t*5)*0.04*Math.abs(rd1);
  const br = lum*edge*shimmer;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*br)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*br)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*br)|0
  ];
}
